  <label class="booking-field"><span>Check-out</span><span class="booking-control"><input type="date" name="end_date" aria-label="Check-out" required><span class="booking-date-display" aria-hidden="true">Choose date</span><span class="booking-chevron" aria-hidden="true"></span></span></label>
  <label class="booking-field booking-adults"><span>Adults</span><span class="booking-control"><select name="adults" aria-label="Adults"><option value="1">1</option><option value="2" selected>2</option><option value="3">3</option><option value="4">4</option><option value="5">5</option><option value="6">6</option><option value="7">7</option><option value="8">8</option><option value="9">9</option><option value="10">10</option><option value="11">11</option></select><span class="booking-chevron" aria-hidden="true"></span></span></label>
  <div class="booking-search-action"><button type="submit">Search</button></div>
</form>
